 },
 {
  "n": 28,
  "section": "Предложение и презентация",
  "title": "Сравнение с конкурентом",
  "prompt": "Клиент сравнивает меня с [конкурент], который предлагает [что и за сколько]. Составь честное сравнение по 5 параметрам, важным клиенту. Где конкурент сильнее — так и напиши. Вывод: кому подхожу я, кому он."
 },
 {
  "n": 29,
  "section": "Предложение и презентация",
  "title": "Пилот вместо большого контракта",
  "prompt": "Клиент [кто] сомневается в проекте на [сумма]. Предложи пилот: что делаем за 2–3 недели, какой измеримый результат, цена, как пилот засчитывается в основной проект. Формулировка для письма до 100 слов."
 },
 {
  "n": 30,
  "section": "Предложение и презентация",
  "title": "Проверка КП",
  "prompt": "Вот моё КП: [текст]. Проверь глазами клиента: понятно ли, что он получит; есть ли следующий шаг; что вызывает сомнение; что можно убрать. Верни список правок по важности и переписанный первый абзац."
 },
 {
  "n": 31,
  "section": "Возражения и переговоры",
  "title": "«Дорого»",
  "prompt": "Клиент сказал «дорого» про [что] за [сумма]. Его ситуация: [факты]. Дай 4 ответа: через цену бездействия, через сравнение с тем, что он делает сейчас, через уменьшение объёма, через уточняющий вопрос. Каждый до 3 предложений."
 },
 {
  "n": 32,
  "section": "Возражения и переговоры",
  "title": "«Нам надо подумать»",
  "prompt": "После КП клиент сказал «надо подумать». Напиши 3 способа выяснить, над чем именно: вопрос о сомнении, вопрос о процессе решения, предложение помочь с внутренним согласованием. И сообщение-напоминание через 4 дня."
 },
 {
  "n": 33,
  "section": "Возражения и переговоры",
  "title": "«У нас уже есть подрядчик»",
  "prompt": "Клиент работает с [конкурент / своей командой]. Напиши 3 ответа, которые не ругают подрядчика: про второй взгляд, про узкую задачу, про проверку на небольшом куске. И вопрос, который выясняет, всем ли он доволен."
 },
 {
  "n": 34,
  "section": "Возражения и переговоры",
  "title": "«Пришлите на почту»",
  "prompt": "Собеседник хочет закончить разговор фразой «пришлите предложение». Дай 3 ответа, которые соглашаются, но получают один уточняющий ответ и договорённость о дате следующего разговора."
 },
 {
  "n": 35,
  "section": "Возражения и переговоры",
  "title": "«Сейчас не время»",
  "prompt": "Клиент откладывает: «вернёмся к этому в следующем квартале». Напиши ответ, который выясняет, что изменится к тому времени, и предлагает маленький шаг сейчас. Плюс напоминание на согласованную дату."
 },
 {
  "n": 36,
  "section": "Возражения и переговоры",
  "title": "Просят скидку",
  "prompt": "Клиент просит скидку [размер] на [что]. Дай 4 варианта ответа: обмен скидки на объём, на срок оплаты, на отзыв или кейс, и вежливый отказ с объяснением. Скидка без встречного условия — не вариант."
 },
 {
  "n": 37,
  "section": "Возражения и переговоры",
  "title": "Меняют условия в последний момент",
  "prompt": "Перед подписанием клиент хочет [изменение]. Для меня это значит [последствия]. Напиши ответ: что я могу принять, что нет и почему, что предлагаю взамен. Тон спокойный, без уступок по умолчанию."
 },
 {
  "n": 38,
  "section": "Возражения и переговоры",
  "title": "Сомнение в результате",
  "prompt": "Клиент спрашивает «а вдруг не сработает?» про [что]. Напиши ответ: от чего зависит результат, что я контролирую, что зависит от него, как мы узнаем на раннем этапе, что идём не туда. Без гарантий, которые я не могу дать."
 },
 {
  "n": 39,
  "section": "Возражения и переговоры",
  "title": "Сравнение по цене",
  "prompt": "Клиент нашёл [что] дешевле на [разница]. Напиши ответ, который не оправдывается: 3 вопроса, чтобы сравнить состав предложения, и что именно входит у меня. Если после сравнения дешёвый вариант ему подходит — так и сказать."
 },
 {
  "n": 40,
  "section": "Возражения и переговоры",
  "title": "План переговоров",
  "prompt": "Переговоры с [кто] о [что]. Моя цель: [что]. Минимум, на который соглашусь: [что]. Его интересы: [что]. Составь план: с чего начать, что предложить первым, чем могу уступить и что попросить взамен, когда встать и уйти."
 },
 {
  "n": 41,
  "section": "Закрытие и работа с клиентом",
  "title": "Следующий шаг с датой",
  "prompt": "Клиент согласен «в целом», но шаг не назначен. Напиши 3 формулировки, которые превращают «да, интересно» в конкретное действие с датой: подписание, оплата, первая встреча. Без давления и «давайте уже решим»."
 },
 {
  "n": 42,
  "section": "Закрытие и работа с клиентом",
  "title": "Письмо со счётом",
  "prompt": "Отправляю счёт на [сумма] за [что]. Напиши письмо до 70 слов: за что счёт, срок оплаты, что происходит сразу после оплаты, к кому обращаться по вопросам."
 },
 {
  "n": 43,
  "section": "Закрытие и работа с клиентом",
  "title": "Старт работы",
  "prompt": "Клиент оплатил [что]. Напиши приветственное письмо: что происходит в первую неделю, что нужно от клиента и к какому числу, как мы общаемся, когда первый результат. До 150 слов."
 },
 {
  "n": 44,
  "section": "Закрытие и работа с клиентом",
  "title": "Запрос отзыва",
  "prompt": "Проект [что] завершён, результат: [цифры]. Напиши сообщение с просьбой об отзыве и 4 вопроса-подсказки, по которым его легко написать: что было до, что сомневало, что получилось, кому порекомендовал бы."
 },
 {
  "n": 45,
  "section": "Закрытие и работа с клиентом",
  "title": "Продление контракта",
  "prompt": "Контракт с [кто] заканчивается через [срок]. Результаты: [цифры]. Напиши письмо о продлении: что сделано, что предлагаю на следующий период, условия, срок ответа. Без «хотели бы уточнить ваши планы»."
 },
 {
  "n": 46,
  "section": "Закрытие и работа с клиентом",
  "title": "Дополнительная продажа",
  "prompt": "Клиент пользуется [что], видна следующая задача: [что]. Напиши сообщение до 80 слов: что я заметил в его данных, чем это грозит, что предлагаю, сколько стоит. Одно предложение, не каталог."
 },
 {
  "n": 47,
  "section": "Закрытие и работа с клиентом",
  "title": "Возврат клиента",
  "prompt": "Клиент [кто] перестал покупать [срок] назад, причина неизвестна. Напиши 2 сообщения: первое — прямой вопрос, что пошло не так; второе, через неделю — что изменилось у нас. Без скидки в первом."
 },
 {
  "n": 48,
  "section": "Закрытие и работа с клиентом",
  "title": "Ответ на жалобу",
  "prompt": "Клиент недоволен: [текст жалобы]. Что произошло на самом деле: [факты]. Напиши ответ: признать то, что правда, объяснить без оправданий, что делаем и к какому сроку, как убедимся, что не повторится."
 },
 {
  "n": 49,
  "section": "Закрытие и работа с клиентом",
  "title": "Разбор недели продаж",
  "prompt": "Мои действия за неделю: [числа касаний, созвонов, КП, сделок]. Найди самое узкое место воронки. Дай 3 гипотезы, почему оно там, и по одному действию на следующую неделю для проверки каждой."
 },
 {
  "n": 50,
  "section": "Закрытие и работа с клиентом",
  "title": "Личный скрипт из лучших фраз",
  "prompt": "Вот фразы, которые сработали у меня в разных сделках: [список]. Собери из них личный скрипт: открытие, вопросы, презентация, ответы на 3 частых возражения, закрытие. Сохрани мои формулировки, не приглаживай."
 }
]

seo-prompt-vault.body:
[
 {
  "n": 1,
  "section": "Семантика и структура сайта",
  "title": "Кластеры запросов",
  "prompt": "Тема: [ниша], регион: [где]. Собери 30 запросов и разложи по кластерам. У каждого кластера: общий интент, тип страницы, главный запрос, 4–5 дополнительных. Отметь кластеры, под которые нужна отдельная страница, а не раздел."
 },
 {
  "n": 2,
  "section": "Семантика и структура сайта",
  "title": "Интент запроса",
  "prompt": "Вот запросы: [список]. Для каждого определи интент — узнать, сравнить, купить, найти конкретное — и что человек хочет увидеть в первом экране. Запросы со смешанным интентом пометь отдельно и предложи, как их разделить."
 },
 {
  "n": 3,
  "section": "Семантика и структура сайта",
  "title": "Карта сайта под семантику",
  "prompt": "Бизнес: [что], услуги: [список], города: [список]. Спроектируй структуру сайта: разделы, страницы услуг, страницы под города, блог. Для каждой страницы — главный запрос и чем она отличается от соседних, чтобы не было каннибализации."
 },
 {
  "n": 4,
  "section": "Семантика и структура сайта",
  "title": "Длинный хвост",
  "prompt": "Главный запрос: [ключ]. Дай 25 длинных запросов вокруг него: с уточнением цены, срока, места, сравнения, проблемы. Сгруппируй по тому, на какой странице на них отвечать — на основной или в отдельной статье."
 },
 {
  "n": 5,
  "section": "Семантика и структура сайта",
  "title": "Вопросы аудитории",
  "prompt": "Тема: [тема], аудитория: [кто]. Собери 20 вопросов, которые люди задают до покупки, во время выбора и после. Сформулируй так, как их пишут в поиске. Отметь 5, на которые можно ответить в блоке FAQ, и 5 — на отдельную статью."
 },
 {
  "n": 6,
  "section": "Семантика и структура сайта",
  "title": "Каннибализация",
  "prompt": "Вот страницы сайта и их запросы: [таблица]. Найди пары страниц, которые соревнуются за один запрос. Для каждой пары: какую оставить основной, что сделать со второй — объединить, переписать под другой интент или поставить редирект."
 },
 {
  "n": 7,
  "section": "Семантика и структура сайта",
  "title": "Запросы под услугу и город",
  "prompt": "Услуга: [что], города: [список]. Составь шаблон семантики для страницы «услуга + город»: обязательные запросы, локальные уточнения, вопросы. Что на странице должно быть уникальным для города, чтобы это не был дубль."
 },
 {
  "n": 8,
  "section": "Семантика и структура сайта",
  "title": "Сезонность и приоритеты",
  "prompt": "Запросы: [список с частотностью, если есть]. Разложи по приоритету: что даёт заявки сейчас, что вырастет в сезон [когда], что работает на узнаваемость. Предложи порядок создания страниц на 3 месяца."
 },
 {
  "n": 9,
  "section": "Семантика и структура сайта",
  "title": "Анализ выдачи",
  "prompt": "По запросу [ключ] в топе такие страницы: [заголовки и краткие описания]. Что у них общего: формат, объём, блоки? Чего нет ни у кого? Составь требования к моей странице: что обязательно повторить, чем отличиться."
 },
 {
  "n": 10,
  "section": "Семантика и структура сайта",
  "title": "Минус-слова и мусорные запросы",
  "prompt": "Ниша: [что]. Вот список собранных запросов: [список]. Отфильтруй нерелевантные: не тот интент, не тот регион, запросы про бесплатное, про работу, про конкурентов. Объясни в одну строку, почему убираешь каждую группу."
 },
 {
  "n": 11,
  "section": "Статьи и контент",
  "title": "Бриф статьи",
  "prompt": "Запрос: [ключ], интент: [какой]. Составь бриф: обещание заголовка, для кого статья, 6–8 подзаголовков с тезисами, факты, которые нужно проверить, примеры, которые нужны от эксперта, FAQ из 4 вопросов, куда ставим внутренние ссылки."
 },
 {
  "n": 12,
  "section": "Статьи и контент",
  "title": "Заголовки H1 и title",
  "prompt": "Статья о: [тема], главный запрос: [ключ]. Дай 8 вариантов H1 и к каждому title до 60 знаков. Ключ ближе к началу, без «всё, что нужно знать» и «полное руководство», если это не руководство."
 },
 {
  "n": 13,
  "section": "Статьи и контент",
  "title": "Вступление",
  "prompt": "Статья: [тема], читатель пришёл по запросу [ключ]. Напиши вступление до 80 слов: признать его ситуацию, сказать, что он получит из статьи, и сразу дать короткий ответ. Без истории вопроса и «в современном мире»."
 },
 {
  "n": 14,
  "section": "Статьи и контент",
  "title": "Раздел по тезисам",
  "prompt": "Подзаголовок: [текст]. Тезисы: [список]. Напиши раздел до 200 слов: по одному абзацу на тезис, с примером или цифрой. Не добавляй фактов от себя — где нужен факт, поставь метку [нужен источник]."
 },
 {
  "n": 15,
  "section": "Статьи и контент",
  "title": "Экспертность в тексте",
  "prompt": "Вот черновик статьи: [текст]. Найди места, где нужен опыт практика: пример из работы, оговорка, типичная ошибка, цифра из практики. Составь список вопросов к эксперту — по одному на каждое такое место."
 },
 {
  "n": 16,
  "section": "Статьи и контент",
  "title": "Блок FAQ",
  "prompt": "Статья: [тема]. Напиши FAQ из 6 вопросов, которые остались без ответа в основном тексте. Ответы по 2–3 предложения, начинаются с сути. Формулировки вопросов — как в поиске."
 },
 {
  "n": 17,
  "section": "Статьи и контент",
  "title": "Редактура воды",
  "prompt": "Вот текст: [текст]. Убери всё, что можно вычеркнуть без потери смысла: вводные слова, повторы, общие фразы. Сохрани структуру и ключевые запросы. Покажи, на сколько процентов сократил и что именно убрал."
 },
 {
  "n": 18,
  "section": "Статьи и контент",
  "title": "Обновление старой статьи",
  "prompt": "Статья от [дата]: [текст]. Запрос: [ключ]. Что устарело, чего не хватает по сравнению с тем, что ищут сейчас, какие разделы добавить, какие сократить. Дай план обновления по шагам."
 },
 {
  "n": 19,
  "section": "Статьи и контент",
  "title": "Статья-сравнение",
  "prompt": "Сравниваю [вариант А] и [вариант Б] для [задача]. Составь структуру: кому что подходит в одном абзаце, таблица по 6 параметрам, разбор по сценариям, честные минусы каждого. Вывод — по ситуациям, а не «выбирать вам»."
 },
 {
  "n": 20,
  "section": "Статьи и контент",
  "title": "Сниппет для блока ответа",
  "prompt": "Запрос-вопрос: [запрос]. Напиши ответ в 40–50 слов, который можно поставить в начало статьи: определение или прямой ответ, без вступления. И вариант списком из 5 шагов, если вопрос про «как»."
 },
 {
  "n": 21,
  "section": "Страницы услуг и товаров",
  "title": "Страница услуги",
  "prompt": "Услуга: [что], регион: [где], главный запрос: [ключ]. Составь структуру страницы: первый экран, для кого, что входит, как проходит работа, цена и от чего зависит, сроки, кейсы, FAQ, форма. Для каждого блока — что там написать."
 },
 {
  "n": 22,
  "section": "Страницы услуг и товаров",
  "title": "Карточка товара",
  "prompt": "Товар: [название, характеристики], аудитория: [кто]. Напиши описание до 150 слов: для чего товар, главные свойства через пользу, кому не подойдёт, что в комплекте. Характеристики — отдельным списком."
 },
 {
  "n": 23,
  "section": "Страницы услуг и товаров",
  "title": "Страница категории",
  "prompt": "Категория: [что], в ней [число] товаров. Напиши текст для страницы категории до 200 слов: как выбрать, чем отличаются подгруппы, ссылки на подкатегории. Текст помогает выбрать, а не перечисляет ключи."
 },
 {
  "n": 24,
  "section": "Страницы услуг и товаров",
  "title": "Локальная страница",
  "prompt": "Услуга: [что], город: [город]. Что на странице должно быть действительно про этот город: адрес, районы, сроки выезда, местные примеры. Напиши структуру и текст первого экрана. Без «в городе N мы предлагаем»."
 },
 {
  "n": 25,
  "section": "Страницы услуг и товаров",
  "title": "Блок цен",
  "prompt": "Услуга: [что], цена зависит от: [факторы]. Напиши блок «Сколько стоит»: диапазон, что в него входит, 3 примера расчёта, что увеличивает цену. Честно, без «цена по запросу»."
 },
 {
  "n": 26,
